using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns relevant search results.")]
string WebSearch(string query)
{
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

    // Simulated search results for demonstration purposes.
    // Replace with a real search API (e.g., Bing Search) for production use.
    var results = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] = """
            1. Quantum computers use qubits that can exist in superposition, enabling parallel computation.
            2. Google achieved quantum supremacy in 2019 with their Sycamore processor (53 qubits).
            3. IBM launched a 1,121-qubit processor (Condor) in 2023 and targets error-corrected systems by 2029.
            4. Key applications include cryptography, drug discovery, materials science, and optimization.
            5. Major challenges remain: decoherence, error rates, and extreme cooling requirements.
            """,
        ["AI agents"] = """
            1. AI agents are autonomous systems that perceive, reason, and act to achieve goals.
            2. Modern agents use LLMs as reasoning engines combined with external tools.
            3. ReAct (Reasoning + Acting) is a popular agent architecture pattern.
            4. Tool use allows agents to search the web, run code, and interact with APIs.
            5. Multi-agent systems enable collaboration between specialized agents.
            """,
        ["climate change solutions"] = """
            1. Renewable energy (solar, wind) costs have dropped 90% in the last decade.
            2. Carbon capture technology is scaling but remains expensive at $250-600/ton.
            3. Electric vehicles reached 18% of global new car sales in 2024.
            4. Green hydrogen is emerging for hard-to-decarbonize sectors like steel and shipping.
            5. Nature-based solutions (reforestation, wetlands) can offset 5-12 Gt CO2/year.
            """,
    };

    // Return matching results or a generic response
    foreach (var kvp in results)
    {
        if (query.Contains(kvp.Key, StringComparison.OrdinalIgnoreCase))
            return kvp.Value;
    }

    return $"Search results for '{query}': Found general information about the topic. "
         + "Key findings suggest this is an active area of research with multiple perspectives.";
}

[Description("Save a note to the research notebook. Use this to record key findings and insights.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s) in your notebook.";
}

[Description("Retrieve all saved notes from the research notebook.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    return "Current research notes:\n" + string.Join("\n", notes.Select((n, i) => $"  {i + 1}. {n}"));
}

// --- Agent Setup ---

Console.WriteLine("Research Agent Starting...\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(TakeNote),
    AIFunctionFactory.Create(GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- Agent Loop ---

var topic = args.Length > 0 ? string.Join(" ", args) : "quantum computing";
Console.WriteLine($"Researching topic: \"{topic}\"\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly by:
        1. Searching the web for relevant information
        2. Taking notes on key findings
        3. Providing a well-organized summary of your research

        Always search first, take notes on important findings, then produce a final summary.
        Use multiple searches if needed to cover different aspects of the topic.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("--- Agent Working ---\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n--- Research Complete ---\n");
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine("\n--- Saved Research Notes ---");
    for (int i = 0; i < notes.Count; i++)
        Console.WriteLine($"  {i + 1}. {notes[i]}");
}

