+Console.WriteLine("Research Agent Starting...\n");
+
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
+var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
+
+IChatClient client = new ChatClientBuilder(
+        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
+    .UseFunctionInvocation()
+    .Build();
+
+var tools = new[]
+{
+    AIFunctionFactory.Create(WebSearch),
+    AIFunctionFactory.Create(TakeNote),
+    AIFunctionFactory.Create(GetNotes),
+};
+
+var chatOptions = new ChatOptions { Tools = [.. tools] };
+
+// --- Agent Loop ---
+
+var topic = args.Length > 0 ? string.Join(" ", args) : "quantum computing";
+Console.WriteLine($"Researching topic: \"{topic}\"\n");
+
+var messages = new List<ChatMessage>
+{
+    new(ChatRole.System, """
+        You are a research agent. Your job is to research a given topic thoroughly by:
+        1. Searching the web for relevant information
+        2. Taking notes on key findings
+        3. Providing a well-organized summary of your research
+
+        Always search first, take notes on important findings, then produce a final summary.
+        Use multiple searches if needed to cover different aspects of the topic.
+        """),
+    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
+};
+
+Console.WriteLine("--- Agent Working ---\n");
+
+var response = await client.GetResponseAsync(messages, chatOptions);
+
+Console.WriteLine("\n--- Research Complete ---\n");
+Console.WriteLine(response.Text);
+
+if (notes.Count > 0)
+{
+    Console.WriteLine("\n--- Saved Research Notes ---");
+    for (int i = 0; i < notes.Count; i++)
+        Console.WriteLine($"  {i + 1}. {notes[i]}");
+}
